import XCTest

final class RoomUITests: XCTestCase {
    let outDir = "/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode"

    override func setUpWithError() throws {
        continueAfterFailure = false
    }

    private func dump(_ app: XCUIApplication, _ name: String) {
        let path = "\(outDir)/\(name).txt"
        try? app.debugDescription.write(toFile: path, atomically: true, encoding: .utf8)
    }

    func testOpenWeekendPlans() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.launch()

        if app.buttons["Open"].waitForExistence(timeout: 5) {
            app.buttons["Open"].tap()
        }

        let wp = app.staticTexts["Weekend Plans"].firstMatch
        XCTAssertTrue(wp.waitForExistence(timeout: 30), "Weekend Plans cell not found")
        wp.tap()

        let composer = app.textViews.firstMatch
        let found = composer.waitForExistence(timeout: 30)
        dump(app, "hier_room")
        XCTAssertTrue(found, "composer not found")
    }
}
